const reply = items[0].json.output;

return [
  {
    json: {
      status: "success",
      message: "Prosedur & Analisis Berhasil",
      data: {
        reply: reply,
        timestamp: new Date().toISOString()
      }
    }
  }
];

const allItems = $input.all();
let fullText = "";

if (allItems.length > 1) {
  fullText = allItems.map(item => Object.values(item.json).join(", ")).join("\n");
} else if (allItems.length === 1) {
  fullText = allItems[0].json.text || allItems[0].json.textContent || allItems[0].json.data || "";
}

if (!fullText || fullText.trim().length === 0) {
  return [{ json: { pageContent: "KOSONG", status: "no_data" } }];
}

const chunks = [];
const CHUNK_SIZE = 1000;

const isCSV = (fullText.match(/,/g) || []).length > (fullText.length * 0.05);
const isLog = (fullText.match(/\[(INFO|ERROR|WARN|DEBUG)\]/i) || []).length > 0 || (fullText.match(/\d{4}-\d{2}-\d{2}/g) || []).length > 5;

if (isCSV || isLog) {
  const lines = fullText.split(/\r?\n/);
  let currentChunkLines = [];
  let currentLength = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    if (currentLength + line.length + 1 > CHUNK_SIZE && currentChunkLines.length > 0) {
      const chunkText = currentChunkLines.join("\n");
      chunks.push({
        json: {
          pageContent: chunkText,
          metadata: { source: "csv_line_chunker", chunkLength: chunkText.length }
        }
      });

      currentChunkLines = currentChunkLines.slice(-2);
      currentLength = currentChunkLines.join("\n").length;
    }

    currentChunkLines.push(line);
    currentLength += line.length + 1;
  }

  if (currentChunkLines.length > 0) {
    const finalChunkText = currentChunkLines.join("\n");
    chunks.push({
      json: {
        pageContent: finalChunkText,
        metadata: { source: "csv_line_chunker", chunkLength: finalChunkText.length }
      }
    });
  }

} else {
  const words = fullText.split(/\s+/);
  let currentChunkWords = [];
  let currentLength = 0;

  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    if (currentLength + word.length + 1 > CHUNK_SIZE && currentChunkWords.length > 0) {
      const chunkText = currentChunkWords.join(" ");
      chunks.push({
        json: {
          pageContent: chunkText,
          metadata: { source: "fast_word_chunker", chunkLength: chunkText.length }
        }
      });
      currentChunkWords = currentChunkWords.slice(-5);
      currentLength = currentChunkWords.join(" ").length;
    }
    currentChunkWords.push(word);
    currentLength += word.length + 1;
  }

  if (currentChunkWords.length > 0) {
    const finalChunkText = currentChunkWords.join(" ");
    chunks.push({
      json: {
        pageContent: finalChunkText,
        metadata: { source: "fast_word_chunker", chunkLength: finalChunkText.length }
      }
    });
  }
}

return chunks;
